double x=p[i*3],y=p[i*3+1],z=clamp(p[i*3+2],0.,15.);
double W=max(0.,1.187*z-.3)/PX,D=z>0?(1.38+1.075*z)/PX:0.,O=z>0?max(0.,11.15-.0967*pow(z-10.91,2))/PX:0;
w=.02*w+.98*W;d=.02*d+.98*D;
double vx=x-rx,vy=y-ry,L=hypot(vx,vy),o=min(O,L);
